const CATEGORY_LABEL={All:'ALL',Team:'TEAM',Individual:'INDIVIDUAL',Combat:'COMBAT',Racket:'RACKET',Water:'WATER',Motorsport:'MOTOR',Winter:'WINTER',Strength:'POWER',Extreme:'EXTREME'};
