const loadingManager=new THREE.LoadingManager();const gltfLoader=new GLTFLoader(loadingManager);
loadingManager.onProgress=(_,loaded,total)=>{const pct=total?Math.round(loaded/total*100):0;$('#progress-bar').style.width=`${pct}%`;$('#progress-label').textContent=`${pct}%`};
