if(!supportsWebGL()){ $('#webgl-fallback').hidden=false;$('#loading').hidden=true } else init();
function injectUpgradeUI(){const rail=$('.side-rail');if(rail)CATEGORIES.forEach(cat=>{if(!rail.querySelector(`[data-category="${cat}"]`)){const b=document.createElement('button');b.className='category-chip';b.dataset.category=cat;b.textContent=CATEGORY_LABEL[cat];rail.appendChild(b)}});const row=$('.tab-row');if(row&&!row.querySelector('[data-tab="gallery"]')){const b=document.createElement('button');b.className='tab';b.dataset.tab='gallery';b.setAttribute('role','tab');b.textContent='Gallery';row.appendChild(b)}const css=document.createElement('link');css.rel='stylesheet';css.href='./museum-upgrade.css';document.head.appendChild(css);const labelLayer=document.createElement('div');labelLayer.id='world-labels';labelLayer.className='world-labels';document.body.appendChild(labelLayer);const lightbox=document.createElement('div');lightbox.id='gallery-lightbox';lightbox.className='gallery-lightbox';lightbox.setAttribute('aria-hidden','true');lightbox.innerHTML='<button class="lb-close" aria-label="Close gallery">×</button><button class="lb-prev" aria-label="Previous image">‹</button><figure><img alt=""><figcaption></figcaption></figure><button class="lb-next" aria-label="Next image">›</button>';document.body.appendChild(lightbox);const inspector=document.createElement('div');inspector.id='equipment-inspector';inspector.className='equipment-inspector';inspector.setAttribute('aria-hidden','true');inspector.innerHTML='<div class="inspector-shell"><div class="inspector-head"><div><span class="eyebrow">3D EQUIPMENT INSPECTOR</span><h3 id="inspector-title">OBJECT</h3></div><button class="inspector-close close-btn" aria-label="Close 3D inspector">×</button></div><canvas id="inspector-canvas"></canvas><div class="inspector-foot"><span>Drag to rotate • wheel / pinch to zoom</span><button id="inspector-reset" class="secondary-btn">Reset view</button></div></div>';document.body.appendChild(inspector)}
function supportsWebGL(){try{const c=document.createElement('canvas');return !!(c.getContext('webgl2')||c.getContext('webgl'))}catch{return false}}
function init(){renderer=new THREE.WebGLRenderer({canvas:$('#scene'),antialias:!mobile,alpha:false,powerPreference:'high-performance'});renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,mobile?1.1:1.5));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;scene=new THREE.Scene();scene.background=new THREE.Color(0x05070a);scene.fog=new THREE.FogExp2(0x05070a,.016);camera=new THREE.PerspectiveCamera(48,innerWidth/innerHeight,.1,120);camera.position.set(0,10.2,18.8);clock=new THREE.Clock();raycaster=new THREE.Raycaster();pointer=new THREE.Vector2(9,9);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.065;controls.enablePan=false;controls.minDistance=7.5;controls.maxDistance=25;controls.maxPolarAngle=Math.PI*.48;controls.minPolarAngle=Math.PI*.2;controls.target.set(0,.8,0);arenaGroup=new THREE.Group();sportsGroup=new THREE.Group();scene.add(arenaGroup,sportsGroup);makeLights();makeArena();makeSports();makeParticles();bindUI();bindVisibility();bindContextRecovery();$('#sport-count').textContent=SPORTS.length;requestAnimationFrame(finishInitialLoad);animate()}
function finishInitialLoad(){$('#progress-bar').style.width='100%';$('#progress-label').textContent='100%';requestAnimationFrame(()=>{$('#loading').classList.add('done');$('#intro').hidden=false;setTimeout(()=>$('#loading').hidden=true,750)})}
function makeLights(){scene.add(new THREE.HemisphereLight(0x8fb6d9,0x090a0c,.65));const key=new THREE.DirectionalLight(0xffffff,2.05);key.position.set(5,11,7);key.castShadow=true;key.shadow.mapSize.set(mobile?512:1024,mobile?512:1024);key.shadow.camera.near=.5;key.shadow.camera.far=38;scene.add(key);const rim=new THREE.DirectionalLight(0x3d8dff,1.05);rim.position.set(-8,5,-9);scene.add(rim);const fill=new THREE.DirectionalLight(0x78f000,.35);fill.position.set(0,3,9);scene.add(fill)}
function mat(color,metal=.5,rough=.32,emissive=0){return new THREE.MeshStandardMaterial({color,metalness:metal,roughness:rough,emissive,emissiveIntensity:.18})}
function mesh(g,m,pos=[0,0,0],shadow=true){const o=new THREE.Mesh(g,m);o.position.set(...pos);o.castShadow=shadow;o.receiveShadow=shadow;return o}
function makeArena(){const floor=mesh(new THREE.CylinderGeometry(15.7,15.7,.28,72),new THREE.MeshStandardMaterial({color:0x0b0e12,metalness:.68,roughness:.25}),[0,-.25,0],true);arenaGroup.add(floor);const ring=mesh(new THREE.TorusGeometry(13.9,.025,8,128),new THREE.MeshBasicMaterial({color:0x26313b,transparent:true,opacity:.9}),[0,.02,0],false);ring.rotation.x=Math.PI/2;arenaGroup.add(ring);for(let r=4;r<=12;r+=4){const line=mesh(new THREE.TorusGeometry(r,.012,5,96),new THREE.MeshBasicMaterial({color:0x1d252d}),[0,.015,0],false);line.rotation.x=Math.PI/2;arenaGroup.add(line)}}
function makeParticles(){if(reducedMotion)return;const count=mobile?70:190,geo=new THREE.BufferGeometry(),arr=new Float32Array(count*3);for(let i=0;i<count;i++){const a=Math.random()*Math.PI*2,r=4+Math.random()*13;arr[i*3]=Math.cos(a)*r;arr[i*3+1]=1+Math.random()*8;arr[i*3+2]=Math.sin(a)*r}geo.setAttribute('position',new THREE.BufferAttribute(arr,3));const p=new THREE.Points(geo,new THREE.PointsMaterial({color:0x8aa0b3,size:.025,transparent:true,opacity:.45,depthWrite:false}));p.userData.decorativeParticles=true;scene.add(p)}
function makeSports(){const n=SPORTS.length;SPORTS.forEach((sport,i)=>{const a=i/n*Math.PI*2-Math.PI/2,r=i%2?10.8:8.1;const group=new THREE.Group();group.position.set(Math.cos(a)*r,.75,Math.sin(a)*r);group.userData={sport,baseY:.75,hover:false,filtered:false,index:i};const podium=mesh(new THREE.CylinderGeometry(1.08,1.18,.22,32),new THREE.MeshStandardMaterial({color:0x10161c,metalness:.78,roughness:.22,emissive:sport.accent,emissiveIntensity:.035}),[0,-.22,0],false);const halo=mesh(new THREE.TorusGeometry(.86,.025,8,48),new THREE.MeshBasicMaterial({color:sport.accent,transparent:true,opacity:.68}),[0,.01,0],false);halo.rotation.x=Math.PI/2;const icon=buildSportObject(sport);icon.name='icon';icon.position.y=.72;group.add(podium,halo,icon);const hit=mesh(new THREE.SphereGeometry(1.15,10,8),new THREE.MeshBasicMaterial({visible:false}),[0,.72,0],false);hit.userData.owner=group;group.add(hit);interactiveTargets.push(hit);sportsGroup.add(group);sportObjects.set(sport.name,group);createWorldLabel(group,sport)})}
function createWorldLabel(group,sport){const el=document.createElement('button');el.className='world-label';el.type='button';el.innerHTML=`<b>${sport.name}</b><span>${CATEGORY_LABEL[sport.category]||sport.category}</span>`;el.dataset.sport=sport.name;el.onclick=()=>selectSport(sport);$('#world-labels').appendChild(el);labels.set(group,el)}
function buildSportObject(s){const g=new THREE.Group(),c=s.accent,main=mat(c,.28,.32),dark=mat(0x11161b,.72,.26),white=mat(0xf3f5f7,.08,.5),metal=mat(0x9aa5ae,.88,.18);const sph=(r,m=main,seg=30)=>mesh(new THREE.SphereGeometry(r,seg,Math.max(12,Math.round(seg*.65))),m);const cyl=(rt,rb,h,m=main,seg=18)=>mesh(new THREE.CylinderGeometry(rt,rb,h,seg),m);switch(s.kind){case'football':{const b=sph(.63,white,32);const seam=new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.IcosahedronGeometry(.635,2)),new THREE.LineBasicMaterial({color:0x14181c,transparent:true,opacity:.55}));b.add(seam);g.add(b);break}case'basketball':{const b=sph(.64,mat(0xd96b16,.12,.68),32);for(let i=0;i<3;i++){const t=mesh(new THREE.TorusGeometry(.645,.018,6,52),new THREE.MeshBasicMaterial({color:0x1a1411}),[0,0,0],false);t.rotation.set(i===0?Math.PI/2:0,i===1?Math.PI/2:0,i===2?Math.PI/4:0);g.add(t)}g.add(b);break}case'volleyball':{const b=sph(.63,white,32);for(let i=0;i<4;i++){const arc=mesh(new THREE.TorusGeometry(.52,.035,6,40,Math.PI*1.35),mat(i%2?0x2b79ff:0xf5c12d,.05,.45),[0,0,0],false);arc.rotation.set(i*.7,i*.85,i*.3);g.add(arc)}g.add(b);break}case'tennis':{const frame=mesh(new THREE.TorusGeometry(.48,.055,10,48),main,[0,.28,0]);frame.scale.y=1.32;const handle=cyl(.07,.09,.68,dark,12);handle.position.y=-.55;const strings=[];for(let x=-.34;x<=.34;x+=.11)strings.push(mesh(new THREE.BoxGeometry(.012,1.02,.012),white,[x,.28,0],false));for(let y=-.1;y<=.65;y+=.11)strings.push(mesh(new THREE.BoxGeometry(.72,.012,.012),white,[0,y,0],false));const ball=sph(.18,mat(0xdfff33,.02,.62),22);ball.position.set(.75,-.28,.15);g.add(frame,handle,...strings,ball);break}case'tennis-ball':{g.add(sph(.55,mat(0xdfff33,.02,.62),28));break}case'paddle':{const face=mesh(new THREE.CylinderGeometry(.48,.48,.09,34),mat(0xd64242,.08,.52));face.rotation.x=Math.PI/2;const h=mesh(new THREE.BoxGeometry(.2,.65,.1),dark,[0,-.62,0]);const ball=sph(.12,white,18);ball.position.set(.67,.12,.18);g.add(face,h,ball);break}case'boxing':{for(const x of[-.33,.33]){const glove=sph(.42,mat(0xc5222f,.18,.43),26);glove.scale.set(.92,1.12,.9);glove.position.set(x,.12,0);const cuff=mesh(new THREE.CylinderGeometry(.27,.29,.3,20),dark,[x,-.36,0]);g.add(glove,cuff)}break}case'martial':{const belt=mesh(new THREE.TorusGeometry(.55,.12,10,48),main);belt.scale.y=.42;const knot=mesh(new THREE.BoxGeometry(.28,.2,.18),dark,[0,-.05,.52]);const tail1=mesh(new THREE.BoxGeometry(.16,.62,.08),main,[.12,-.45,.5]);tail1.rotation.z=-.2;const tail2=tail1.clone();tail2.position.x=-.12;tail2.rotation.z=.2;g.add(belt,knot,tail1,tail2);break}case'swimming':{for(const x of[-.38,.38]){const lens=mesh(new THREE.CylinderGeometry(.32,.32,.11,28),new THREE.MeshPhysicalMaterial({color:0x3ac6ff,roughness:.08,transmission:.42,transparent:true,opacity:.7}),[x,0,0]);lens.rotation.x=Math.PI/2;g.add(lens)}const bridge=mesh(new THREE.BoxGeometry(.3,.08,.07),dark);const strap=mesh(new THREE.TorusGeometry(.72,.035,8,42,Math.PI),dark,[0,0,-.05],false);strap.rotation.z=Math.PI;g.add(bridge,strap);break}case'running':{const shoe=mesh(new THREE.BoxGeometry(1.25,.43,.56),main,[.05,0,0]);shoe.scale.x=1.08;shoe.geometry.translate(.12,.02,0);const sole=mesh(new THREE.BoxGeometry(1.35,.12,.59),white,[.05,-.27,0]);const heel=mesh(new THREE.BoxGeometry(.35,.45,.58),dark,[-.48,.05,0]);g.add(shoe,sole,heel);break}case'cycling':{for(const x of[-.68,.68]){const w=mesh(new THREE.TorusGeometry(.5,.045,8,36),dark,[x,-.12,0]);w.rotation.y=Math.PI/2;g.add(w)}for(const [x,y,x2,y2] of [[0,0,-.58,.12],[.35,.05,-.5,.55],[-.35,.05,.5,.55]]){const len=Math.hypot(x2-x,y2-y),b=cyl(.035,.035,len,main,8);b.position.set((x+x2)/2,(y+y2)/2,0);b.rotation.z=-Math.atan2(x2-x,y2-y);g.add(b)}const handle=cyl(.025,.025,.58,metal,8);handle.position.set(.62,.55,0);handle.rotation.z=-.1;g.add(handle);break}case'motorsport':{const h=sph(.68,new THREE.MeshPhysicalMaterial({color:c,metalness:.38,roughness:.16,clearcoat:1,clearcoatRoughness:.06}),32);h.scale.y=.9;const cut=mesh(new THREE.BoxGeometry(1.1,.42,.38),dark,[0,-.25,.42]);const visor=mesh(new THREE.BoxGeometry(.98,.25,.08),new THREE.MeshPhysicalMaterial({color:0x07151d,metalness:.45,roughness:.05,transmission:.18,transparent:true,opacity:.82}),[0,.08,.64]);g.add(h,cut,visor);break}case'dumbbell':{const bar=cyl(.06,.06,1.5,metal,14);bar.rotation.z=Math.PI/2;g.add(bar);for(const x of[-.62,.62])for(const o of[-.09,.09]){const w=cyl(.3,.3,.15,dark,24);w.position.x=x+o;w.rotation.z=Math.PI/2;g.add(w)}break}case'barbell':{const bar=cyl(.04,.04,1.85,metal,12);bar.rotation.z=Math.PI/2;g.add(bar);for(const x of[-.73,.73])for(let j=0;j<2;j++){const p=cyl(.36-j*.04,.36-j*.04,.12,j?dark:main,24);p.position.x=x+(x<0?-j*.13:j*.13);p.rotation.z=Math.PI/2;g.add(p)}break}case'golf':{const ball=sph(.23,white,24);ball.position.set(.46,-.22,.08);const shaft=cyl(.022,.027,1.35,metal,8);shaft.position.set(-.22,.08,0);shaft.rotation.z=-.17;const head=mesh(new THREE.BoxGeometry(.38,.13,.15),dark,[-.08,-.58,0]);g.add(ball,shaft,head);break}case'baseball':{const ball=sph(.33,white,24),bat=cyl(.07,.16,1.35,mat(0xb47a3f,.08,.48),18);bat.position.set(.48,0,0);bat.rotation.z=-.52;g.add(ball,bat);break}case'american':{const b=sph(.64,mat(0x743a20,.08,.72),28);b.scale.set(1.28,.74,.74);b.rotation.z=-.15;const lace=mesh(new THREE.BoxGeometry(.44,.04,.06),white,[0,.45,.18],false);g.add(b,lace);break}case'hockey':{const puck=cyl(.34,.34,.12,dark,28);puck.position.set(.32,-.34,.18);const shaft=mesh(new THREE.BoxGeometry(.11,1.48,.11),main,[-.32,.1,0]);shaft.rotation.z=.32;const blade=mesh(new THREE.BoxGeometry(.58,.13,.16),main,[.02,-.58,0]);g.add(puck,shaft,blade);break}case'ski':{for(const x of[-.23,.23]){const sk=mesh(new THREE.BoxGeometry(.14,1.75,.08),main,[x,0,0]);sk.rotation.x=.08;g.add(sk)}for(const x of[-.42,.42]){const pole=cyl(.018,.018,1.5,metal,7);pole.position.x=x;pole.rotation.z=x<0?.12:-.12;g.add(pole)}break}case'snowboard':{const b=mesh(new THREE.BoxGeometry(.55,1.72,.11),main);b.rotation.z=.13;for(const y of[-.28,.28]){const bind=mesh(new THREE.TorusGeometry(.16,.035,8,24,Math.PI),dark,[0,y,.11]);g.add(bind)}g.add(b);break}case'skateboard':{const deck=mesh(new THREE.BoxGeometry(1.45,.13,.48),main);for(const x of[-.5,.5]){const truck=mesh(new THREE.BoxGeometry(.12,.16,.65),metal,[x,-.15,0]);g.add(truck);for(const z of[-.3,.3]){const wheel=cyl(.1,.1,.08,dark,14);wheel.position.set(x,-.25,z);wheel.rotation.x=Math.PI/2;g.add(wheel)}}g.add(deck);break}case'surf':{const b=mesh(new THREE.CapsuleGeometry(.27,.95,8,20),main);b.rotation.z=Math.PI/2;b.scale.y=.72;g.add(b);break}case'archery':{const curve=new THREE.CatmullRomCurve3([new THREE.Vector3(0,-.75,0),new THREE.Vector3(-.32,-.4,0),new THREE.Vector3(-.42,0,0),new THREE.Vector3(-.32,.4,0),new THREE.Vector3(0,.75,0)]);const bow=mesh(new THREE.TubeGeometry(curve,32,.035,8,false),main);const str=mesh(new THREE.BoxGeometry(.015,1.52,.015),white,[0,0,0],false);const arrow=cyl(.018,.018,1.25,metal,7);arrow.rotation.z=Math.PI/2;arrow.position.set(.16,0,.08);g.add(bow,str,arrow);break}case'fencing':{const blade=cyl(.018,.012,1.45,metal,8);blade.rotation.z=-.14;const guard=mesh(new THREE.SphereGeometry(.22,18,10,0,Math.PI*2,0,Math.PI/2),main,[.1,-.7,0]);guard.rotation.x=Math.PI;const grip=cyl(.06,.07,.3,dark,10);grip.position.set(.14,-.86,0);grip.rotation.z=-.14;g.add(blade,guard,grip);break}case'wrestling':{const matDisc=cyl(.9,.9,.08,main,40);matDisc.position.y=-.3;const ring=mesh(new THREE.TorusGeometry(.62,.028,8,36),white,[0,-.25,0],false);ring.rotation.x=Math.PI/2;const dummy=mesh(new THREE.CapsuleGeometry(.22,.55,8,14),dark,[0,.28,0]);g.add(matDisc,ring,dummy);break}case'badminton':{const frame=mesh(new THREE.TorusGeometry(.42,.045,9,42),main,[0,.3,0]);frame.scale.y=1.25;const h=cyl(.045,.055,.75,dark,10);h.position.y=-.58;const shuttle=cyl(.12,.04,.28,white,12);shuttle.position.set(.68,-.15,.1);shuttle.rotation.z=.6;g.add(frame,h,shuttle);break}case'climbing':{for(const x of[-.32,.05,.4]){const car=mesh(new THREE.TorusGeometry(.24,.045,8,24),x===.05?main:metal,[x,0,0]);car.scale.y=1.2;g.add(car)}const rope=mesh(new THREE.TorusGeometry(.62,.035,8,42),mat(0xf45c43,.05,.7));rope.position.y=-.15;g.add(rope);break}}g.rotation.x=.08;g.rotation.y=-.35;return g}
function bindUI(){$('#enter-arena')?.addEventListener('click',leaveIntro);$('#skip-intro')?.addEventListener('click',leaveIntro);$('#close-detail')?.addEventListener('click',closeDetail);$('#back-btn')?.addEventListener('click',closeDetail);$('#open-search')?.addEventListener('click',()=>togglePanel('#search-panel',true));$('#close-search')?.addEventListener('click',()=>togglePanel('#search-panel',false));$('#help-toggle')?.addEventListener('click',()=>togglePanel('#help-panel',true));$('#close-help')?.addEventListener('click',()=>togglePanel('#help-panel',false));$('#sound-toggle')?.addEventListener('click',()=>{audioEnabled=!audioEnabled;$('#sound-toggle').classList.toggle('active',audioEnabled)});$$('.category-chip').forEach(b=>b.addEventListener('click',()=>filterCategory(b.dataset.category)));$$('.tab').forEach(b=>b.addEventListener('click',()=>{currentTab=b.dataset.tab;$$('.tab').forEach(x=>x.classList.toggle('active',x===b));renderTab()}));$('#search-input')?.addEventListener('input',renderSearch);$('#scene').addEventListener('pointermove',onPointerMove,{passive:true});$('#scene').addEventListener('pointerdown',onPointerDown,{passive:true});$('#scene').addEventListener('pointerleave',clearHover,{passive:true});window.addEventListener('resize',onResize,{passive:true});document.addEventListener('keydown',onKey);$('#gallery-lightbox .lb-close').onclick=closeLightbox;$('#gallery-lightbox').addEventListener('click',e=>{if(e.target.id==='gallery-lightbox')closeLightbox()});$('#equipment-inspector .inspector-close').onclick=closeInspector;$('#sport-symbol-strip')?.addEventListener('click',e=>{const b=e.target.closest('.sport-symbol');if(b){const s=SPORTS.find(x=>x.name===b.dataset.sport);if(s)selectSport(s)}});renderSearch()}
function leaveIntro(){$('#intro').classList.add('leaving');setTimeout(()=>$('#intro').hidden=true,900)}function togglePanel(sel,open){const el=$(sel);if(!el)return;el.classList.toggle('open',open);el.setAttribute('aria-hidden',String(!open));if(open&&sel==='#search-panel')setTimeout(()=>$('#search-input')?.focus(),80)}
function onKey(e){if(e.key==='Escape'){if($('#gallery-lightbox').classList.contains('open'))closeLightbox();else if($('#equipment-inspector').classList.contains('open'))closeInspector();else if($('#search-panel').classList.contains('open'))togglePanel('#search-panel',false);else if($('#help-panel').classList.contains('open'))togglePanel('#help-panel',false);else if(currentSport)closeDetail()}if(e.key==='ArrowLeft'&&$('#gallery-lightbox').classList.contains('open'))stepLightbox(-1);if(e.key==='ArrowRight'&&$('#gallery-lightbox').classList.contains('open'))stepLightbox(1)}
function filterCategory(cat='All'){activeCategory=cat;$$('.category-chip').forEach(b=>b.classList.toggle('active',b.dataset.category===cat));sportObjects.forEach(g=>{const match=cat==='All'||g.userData.sport.category===cat;g.userData.filtered=!match;g.visible=match;const label=labels.get(g);if(label)label.hidden=!match});$$('#sport-symbol-strip .sport-symbol').forEach(b=>{const s=SPORTS.find(x=>x.name===b.dataset.sport);b.hidden=!!s&&(cat!=='All'&&s.category!==cat)});$('#status-text').textContent=`${CATEGORY_LABEL[cat]||cat.toUpperCase()} • ${[...sportObjects.values()].filter(x=>x.visible).length} SPORTS`;clearHover()}
function updatePointer(e){const rect=renderer.domElement.getBoundingClientRect();pointer.x=(e.clientX-rect.left)/rect.width*2-1;pointer.y=-(e.clientY-rect.top)/rect.height*2+1}function onPointerMove(e){updatePointer(e);pointerDirty=true}function onPointerDown(e){updatePointer(e);performRaycast(true)}
function performRaycast(select=false){const now=performance.now();if(!select&&now-lastRay<45)return;lastRay=now;pointerDirty=false;raycaster.setFromCamera(pointer,camera);const hits=raycaster.intersectObjects(interactiveTargets,false).filter(h=>h.object.visible&&h.object.parent?.visible);const owner=hits[0]?.object.userData.owner||null;if(select&&owner){selectSport(owner.userData.sport);return}if(owner!==hovered){if(hovered)hovered.userData.hover=false;hovered=owner;if(hovered)hovered.userData.hover=true;updatePointerLabel()}}
function updatePointerLabel(){const label=$('#pointer-label');if(!hovered){label.hidden=true;return}label.hidden=false;label.textContent=`${hovered.userData.sport.name.toUpperCase()} • ${CATEGORY_LABEL[hovered.userData.sport.category]||hovered.userData.sport.category}`}
function clearHover(){if(hovered)hovered.userData.hover=false;hovered=null;$('#pointer-label').hidden=true}
let desiredCamera=new THREE.Vector3(0,10.2,18.8),desiredTarget=new THREE.Vector3(0,.8,0);
function selectSport(sport){currentSport=sport;selectedObj=sportObjects.get(sport.name);currentTab='overview';cameraMode='detail';$('#detail-name').textContent=sport.name.toUpperCase();$('#detail-category').textContent=`${CATEGORY_LABEL[sport.category]||sport.category.toUpperCase()} SPORT`;$('#detail-panel').classList.add('open');$('#detail-panel').setAttribute('aria-hidden','false');$('#hero-hud').classList.add('hidden');$$('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab==='overview'));renderTab();const p=selectedObj.position.clone(),dir=p.clone().normalize(),side=new THREE.Vector3(-dir.z,0,dir.x);const offset=mobile?dir.multiplyScalar(5.4).add(new THREE.Vector3(0,3.6,0)):dir.multiplyScalar(5.4).add(side.multiplyScalar(-2.2)).add(new THREE.Vector3(0,2.8,0));desiredCamera=p.clone().add(offset);desiredTarget=p.clone().add(new THREE.Vector3(0,.8,0));controls.enabled=false;sportObjects.forEach(g=>{g.userData.dimmed=g!==selectedObj;labels.get(g)?.classList.toggle('dimmed',g!==selectedObj)});$('#status-text').textContent=`INSPECTING ${sport.name.toUpperCase()}`}
function closeDetail(){currentSport=null;selectedObj=null;cameraMode='arena';$('#detail-panel').classList.remove('open');$('#detail-panel').setAttribute('aria-hidden','true');$('#hero-hud').classList.remove('hidden');controls.enabled=true;controls.target.set(0,.8,0);sportObjects.forEach(g=>{g.userData.dimmed=false;labels.get(g)?.classList.remove('dimmed')});$('#status-text').textContent='ARENA ONLINE'}
function equipmentPurpose(item,sport){return `${item} is used in ${sport} for control, safety, performance or sport-specific play.`}function clothingPurpose(item,sport){return `${item} supports movement, comfort, protection or competition requirements in ${sport}.`}function safeHTML(s){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
async function fetchCommons(query,limit=1){const key=`${query}|${limit}`;if(imageCache.has(key))return imageCache.get(key);const promise=(async()=>{try{const url='https://commons.wikimedia.org/w/api.php?'+new URLSearchParams({action:'query',generator:'search',gsrsearch:`file:${query}`,gsrnamespace:'6',gsrlimit:String(Math.min(limit,8)),prop:'imageinfo',iiprop:'url|extmetadata',iiurlwidth:'1000',format:'json',origin:'*'});const r=await fetch(url);if(!r.ok)throw new Error(`Commons ${r.status}`);const j=await r.json();return Object.values(j.query?.pages||{}).map(p=>{const ii=p.imageinfo?.[0]||{},m=ii.extmetadata||{};return{url:ii.thumburl||ii.url,title:p.title?.replace(/^File:/,''),artist:(m.Artist?.value||'Wikimedia Commons').replace(/<[^>]*>/g,''),license:m.LicenseShortName?.value||'',page:ii.descriptionurl||''}}).filter(x=>x.url)}catch(e){console.warn(e);return[]}})();imageCache.set(key,promise);return promise}
function cardSkeleton(name,description,kind,index){return `<article class="visual-item" data-kind="${kind}" data-index="${index}"><div class="visual-media skeleton"><img alt="${safeHTML(name)}" loading="lazy" decoding="async"></div><div class="visual-copy"><b>${safeHTML(name)}</b><span>${safeHTML(description)}</span><small class="image-credit"></small>${kind==='equipment'?'<button class="view3d secondary-btn">VIEW IN 3D</button>':''}</div></article>`}
async function hydrateVisualCards(kind,items){const root=$('#tab-content');if(!root||!currentSport)return;const token=currentSport.name+currentTab,cards=$$('.visual-item',root);await Promise.all(cards.map(async(card,i)=>{const item=items[i],img=$('img',card),media=$('.visual-media',card),credit=$('.image-credit',card);const found=await fetchCommons(`${currentSport.name} ${item.name}`,1);if(!currentSport||currentSport.name+currentTab!==token)return;const photo=found[0];img.src=photo?.url||imgFallback(item.name);img.onerror=()=>{img.onerror=null;img.src=imgFallback(item.name)};media.classList.remove('skeleton');credit.textContent=photo?`${photo.artist}${photo.license?` • ${photo.license}`:''}`:'SAEID SPORTS fallback artwork';if(photo?.page)credit.title=photo.page;$('.view3d',card)?.addEventListener('click',()=>openInspector(item.name,currentSport))}))}
async function renderGallery(){const c=$('#tab-content'),sport=currentSport,token=sport.name+'gallery';c.innerHTML='<div class="gallery-grid">'+[0,1,2,3,4,5].map(i=>`<button class="gallery-tile skeleton" data-i="${i}"><img alt="${safeHTML(sport.name)} gallery image ${i+1}" loading="lazy"></button>`).join('')+'</div><p class="source-note">Photography is retrieved from Wikimedia Commons with source/license metadata when available.</p>';const queries=[`${sport.name} sport action`,`${sport.name} venue`,`${sport.name} equipment`];let photos=[];for(const q of queries)photos.push(...await fetchCommons(q,2));photos=photos.filter((p,i,a)=>a.findIndex(x=>x.url===p.url)===i).slice(0,6);if(!currentSport||currentSport.name+'gallery'!==token)return;const fallback={url:sport.image,title:`${sport.name} overview`,artist:'Sport overview photography',license:'',page:''};while(photos.length<6)photos.push(fallback);$$('.gallery-tile',c).forEach((t,i)=>{const p=photos[i],img=$('img',t);img.src=p.url;img.onerror=()=>{img.onerror=null;img.src=imgFallback(sport.name)};t.classList.remove('skeleton');t.onclick=()=>openLightbox(photos,i)})}
function renderTab(){if(!currentSport)return;const s=currentSport,c=$('#tab-content');if(currentTab==='overview'){c.innerHTML=`<p class="panel-copy">${safeHTML(s.overview)}</p><div class="info-stats"><div class="stat"><b>${safeHTML(s.players)}</b><span>PLAYERS</span></div><div class="stat"><b>${safeHTML(s.place)}</b><span>ARENA</span></div><div class="stat"><b>${safeHTML(s.scoring)}</b><span>SCORING</span></div></div><div class="photo-card"><img loading="lazy" decoding="async" src="${s.image}" alt="${safeHTML(s.name)} sports environment"><span>REAL WORLD / ${safeHTML(s.name.toUpperCase())}</span></div><p class="panel-copy">Open Equipment, Clothing or Gallery for visual references and interactive inspection.</p>`;const im=$('.photo-card img',c);im.onerror=()=>{im.onerror=null;im.src=imgFallback(s.name)}}else if(currentTab==='equipment'){c.innerHTML='<p class="panel-copy">Each item has a dedicated visual reference. Open important gear in the embedded 3D inspector.</p><div class="visual-grid">'+s.equipment.map((x,i)=>cardSkeleton(x.name,equipmentPurpose(x.name,s.name),'equipment',i)).join('')+'</div>';hydrateVisualCards('equipment',s.equipment)}else if(currentTab==='clothing'){c.innerHTML='<p class="panel-copy">Sport clothing is shaped by movement, climate, safety and the surface of play.</p><div class="visual-grid">'+s.clothing.map((x,i)=>cardSkeleton(x.name,clothingPurpose(x.name,s.name),'clothing',i)).join('')+'</div>';hydrateVisualCards('clothing',s.clothing)}else if(currentTab==='rules')c.innerHTML=`<ul class="list-clean">${s.rules.map(x=>`<li>${safeHTML(x)}</li>`).join('')}</ul>`;else if(currentTab==='skills')c.innerHTML=`<div class="item-grid">${s.skills.map(x=>`<div class="item"><b>${safeHTML(x)}</b><span>Key performance skill</span></div>`).join('')}</div>`;else if(currentTab==='facts')c.innerHTML=`<ul class="list-clean">${s.facts.map(x=>`<li>${safeHTML(x)}</li>`).join('')}</ul>`;else if(currentTab==='gallery')renderGallery()}
function renderSearch(){const q=($('#search-input')?.value||'').trim().toLowerCase(),root=$('#search-results');if(!root)return;const list=SPORTS.filter(s=>!q||s.name.toLowerCase().includes(q)||s.category.toLowerCase().includes(q));root.innerHTML=list.map(s=>`<button class="search-result" data-name="${safeHTML(s.name)}"><span><b>${safeHTML(s.name)}</b><small>${safeHTML(CATEGORY_LABEL[s.category]||s.category)}</small></span><i>↗</i></button>`).join('');$$('.search-result',root).forEach(b=>b.onclick=()=>{const s=SPORTS.find(x=>x.name===b.dataset.name);if(s){togglePanel('#search-panel',false);selectSport(s)}})}
let lbPhotos=[],lbIndex=0;function openLightbox(photos,index){lbPhotos=photos;lbIndex=index;updateLightbox();const lb=$('#gallery-lightbox');lb.classList.add('open');lb.setAttribute('aria-hidden','false');$('.lb-prev',lb).onclick=()=>stepLightbox(-1);$('.lb-next',lb).onclick=()=>stepLightbox(1)}function updateLightbox(){const p=lbPhotos[lbIndex],lb=$('#gallery-lightbox'),im=$('img',lb);im.src=p.url;im.onerror=()=>{im.onerror=null;im.src=imgFallback(p.title||'SPORT')};$('figcaption',lb).textContent=`${p.title||''}${p.artist?` — ${p.artist}`:''}${p.license?` • ${p.license}`:''}`}function stepLightbox(d){lbIndex=(lbIndex+d+lbPhotos.length)%lbPhotos.length;updateLightbox()}function closeLightbox(){const lb=$('#gallery-lightbox');lb.classList.remove('open');lb.setAttribute('aria-hidden','true')}
let inspectorState=null;function openInspector(itemName,sport){const wrap=$('#equipment-inspector');wrap.classList.add('open');wrap.setAttribute('aria-hidden','false');$('#inspector-title').textContent=itemName.toUpperCase();requestAnimationFrame(()=>setupInspector(itemName,sport))}
function setupInspector(itemName,sport){if(inspectorState){inspectorState.stop();inspectorState.renderer.dispose();inspectorState.controls.dispose()}const canvas=$('#inspector-canvas'),w=canvas.clientWidth||600,h=canvas.clientHeight||380,r=new THREE.WebGLRenderer({canvas,antialias:!mobile,alpha:true,powerPreference:'high-performance'});r.setPixelRatio(Math.min(devicePixelRatio,mobile?1.05:1.35));r.setSize(w,h,false);r.outputColorSpace=THREE.SRGBColorSpace;r.toneMapping=THREE.ACESFilmicToneMapping;const sc=new THREE.Scene(),cam=new THREE.PerspectiveCamera(42,w/h,.1,50);cam.position.set(0,1.2,4.2);const ctr=new OrbitControls(cam,canvas);ctr.enableDamping=true;ctr.enablePan=false;ctr.minDistance=2;ctr.maxDistance=7;sc.add(new THREE.HemisphereLight(0xffffff,0x11131a,1.3));const dl=new THREE.DirectionalLight(0xffffff,2);dl.position.set(3,5,4);sc.add(dl);const display=buildSportObject({...sport,kind:itemKind(itemName,sport.kind)});normalizeModel(display,2);sc.add(display);const base=mesh(new THREE.CylinderGeometry(1.35,1.5,.15,40),new THREE.MeshStandardMaterial({color:0x0d1218,metalness:.7,roughness:.25}),[0,-1.15,0],false);sc.add(base);let running=true;const loop=()=>{if(!running)return;requestAnimationFrame(loop);ctr.update();if(!reducedMotion)display.rotation.y+=.0025;r.render(sc,cam)};loop();inspectorState={renderer:r,controls:ctr,stop:()=>running=false,camera:cam};$('#inspector-reset').onclick=()=>{cam.position.set(0,1.2,4.2);ctr.target.set(0,0,0);ctr.update()}}
function itemKind(name,fallback){const n=name.toLowerCase();if(n.includes('racket'))return n.includes('badminton')?'badminton':'tennis';if(n.includes('ball')&&n.includes('tennis'))return'tennis-ball';if(n.includes('glove'))return'boxing';if(n.includes('helmet'))return'motorsport';if(n.includes('dumbbell'))return'dumbbell';if(n.includes('barbell'))return'barbell';if(n.includes('bat'))return'baseball';if(n.includes('hockey stick'))return'hockey';if(n.includes('skateboard'))return'skateboard';if(n.includes('surfboard'))return'surf';if(n==='bow')return'archery';return fallback}function normalizeModel(model,target=2){const box=new THREE.Box3().setFromObject(model),size=box.getSize(new THREE.Vector3()),center=box.getCenter(new THREE.Vector3()),max=Math.max(size.x,size.y,size.z)||1;model.position.sub(center);model.scale.setScalar(target/max)}
function closeInspector(){const w=$('#equipment-inspector');w.classList.remove('open');w.setAttribute('aria-hidden','true');if(inspectorState){inspectorState.stop();inspectorState.renderer.dispose();inspectorState.controls.dispose();inspectorState=null}}
function bindVisibility(){document.addEventListener('visibilitychange',()=>{pageVisible=document.visibilityState==='visible';if(pageVisible)clock.getDelta()})}function bindContextRecovery(){renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();$('#status-text').textContent='GRAPHICS CONTEXT LOST — RECOVERING'});renderer.domElement.addEventListener('webglcontextrestored',()=>{$('#status-text').textContent='ARENA ONLINE'})}
function animate(){requestAnimationFrame(animate);if(!pageVisible)return;const dt=Math.min(clock.getDelta(),.05),t=clock.elapsedTime;if(pointerDirty)performRaycast(false);updateSports(t,dt);updateWorldLabels();if(cameraMode==='detail'&&currentSport){camera.position.lerp(desiredCamera,1-Math.pow(.001,dt));controls.target.lerp(desiredTarget,1-Math.pow(.001,dt))}if(!reducedMotion&&!currentSport)sportsGroup.rotation.y=Math.sin(t*.06)*.022;const p=scene.children.find(o=>o.userData.decorativeParticles);if(p&&!reducedMotion)p.rotation.y=t*.006;controls.update();renderer.render(scene,camera)}
function updateSports(t,dt){sportObjects.forEach(g=>{if(!g.visible)return;const icon=g.getObjectByName('icon'),target=g===selectedObj?1.15:g.userData.hover?1.1:g.userData.dimmed?.92:1,d=1-Math.pow(.003,dt);g.scale.lerp(new THREE.Vector3(target,target,target),d);if(!reducedMotion&&!g.userData.dimmed){g.position.y=g.userData.baseY+Math.sin(t*1.05+g.userData.index*.7)*.035;if(icon)icon.rotation.y+=dt*(g.userData.hover?.78:.16)}})}
function updateWorldLabels(){const w=innerWidth,h=innerHeight,tmp=new THREE.Vector3();labels.forEach((el,g)=>{if(!g.visible||($('#detail-panel').classList.contains('open')&&g!==selectedObj)){el.style.opacity='0';el.style.pointerEvents='none';return}tmp.setFromMatrixPosition(g.matrixWorld);tmp.y+=2.15;tmp.project(camera);const visible=tmp.z<1&&tmp.x>-1.15&&tmp.x<1.15&&tmp.y>-1.15&&tmp.y<1.15;el.style.opacity=visible?'1':'0';el.style.pointerEvents=visible?'auto':'none';el.style.transform=`translate(-50%,-50%) translate(${(tmp.x*.5+.5)*w}px,${(-tmp.y*.5+.5)*h}px)`})}
function onResize(){mobile=mobileQuery.matches;camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,mobile?1.1:1.5));if(inspectorState){const c=$('#inspector-canvas'),w=c.clientWidth,h=c.clientHeight;inspectorState.renderer.setSize(w,h,false);inspectorState.camera.aspect=w/h;inspectorState.camera.updateProjectionMatrix()}}mobileQuery.addEventListener?.('change',onResize);motionQuery.addEventListener?.('change',e=>reducedMotion=e.matches);window.SAEID_SPORTS={SPORTS,rendererInfo:()=>renderer?.info};